    init {
        val versions = HashMap<String, String>(1078 * 4 / 3 + 1)
        val dates = HashMap<String, String>(1078 * 4 / 3 + 1)
        val tags = HashSet<String>(81 * 4 / 3 + 1)
        for (line in ENTRIES.lineSequence()) {
            if (line.isEmpty()) continue
            val parts = line.split(' ')
            versions[parts[0]] = parts[1]
            dates[parts[0]] = parts[2]
            if (parts.size > 3) tags.add(parts[0])
        }
        prefixToVersion = versions
        prefixToDate = dates
        tagPrefixes = tags
    }

    /** Reported version for a full build-commit SHA (O(1)), or null if unknown. */
    fun versionForCommit(sha: String): String? {
        if (sha.length < PREFIX_LEN) return null
        return prefixToVersion[sha.substring(0, PREFIX_LEN).lowercase()]
    }

    /** ISO committer date (yyyy-MM-dd) of a build commit, or null if unknown. */
    fun dateForCommit(sha: String): String? {
        if (sha.length < PREFIX_LEN) return null
        return prefixToDate[sha.substring(0, PREFIX_LEN).lowercase()]
    }

    /** OFFICIAL (release tag), RC (prerelease tag), or DEV (untagged); null if unknown. */
    fun classificationForCommit(sha: String): String? {
        if (sha.length < PREFIX_LEN) return null
        val key = sha.substring(0, PREFIX_LEN).lowercase()
        val version = prefixToVersion[key]?.lowercase() ?: return null
        return when {
            key !in tagPrefixes -> "DEV"
            "-rc" in version || "-beta" in version || "-alpha" in version -> "RC"
            else -> "OFFICIAL"
        }
    }
}
